//! Embedded EPSG table: every 2D geographic and projected CRS of the EPSG Geodetic Parameter Dataset that GeoTools
//! (`gt-epsg-hsql`, which planetiler Java uses) can decode, converted to PROJ strings.
//!
//! `epsg.tsv.zst` is generated by [`tests::generate_epsg_table`] from the output of `tools/crs/DumpEpsg.java`, which
//! dumps each CRS from GeoTools as WKT together with the datum shift GeoTools uses to get to WGS84, its EPSG axis
//! order and reference coordinates computed by GeoTools; every entry is checked against those reference coordinates
//! when the table is generated.
//!
//! Each line is `code<TAB>flags<TAB>proj string`, where flags is the GeoTools `CRS.getAxisOrder` of the CRS with EPSG
//! axis order (`E` east/north, `N` north/east, `I` inapplicable), followed by `:<radians per unit>` for geographic
//! CRS in a unit other than degrees, or `X` for CRS that GeoTools supports but this port does not, in which case the
//! third column is the reason.

use std::sync::OnceLock;

use super::{AxisOrder, CrsDef, DEGREE};

static DATA: &[u8] = include_bytes!("epsg.tsv.zst");

pub(crate) enum Entry {
    Supported(CrsDef),
    Unsupported(&'static str),
}

fn table() -> &'static [(u32, &'static str, &'static str)] {
    static TABLE: OnceLock<Vec<(u32, &'static str, &'static str)>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let text = zstd::stream::decode_all(DATA).expect("invalid embedded EPSG table");
        let text: &'static str = String::from_utf8(text).expect("invalid embedded EPSG table").leak();
        let mut result: Vec<_> = text
            .lines()
            .filter_map(|line| {
                let mut parts = line.splitn(3, '\t');
                let code = parts.next()?.parse().ok()?;
                Some((code, parts.next()?, parts.next()?))
            })
            .collect();
        result.sort_unstable_by_key(|e| e.0);
        result
    })
}

/// Number of EPSG codes in the embedded table (supported + unsupported).
pub(crate) fn len() -> usize {
    table().len()
}

/// Look up an EPSG code, with the axis order from the EPSG database (latitude first for most geographic CRS).
pub(crate) fn lookup(code: u32) -> Option<Entry> {
    let table = table();
    let idx = table.binary_search_by_key(&code, |e| e.0).ok()?;
    let (_, flags, proj) = table[idx];
    let (order, unit) = flags.split_once(':').unwrap_or((flags, ""));
    let axis_order = match order {
        "E" => AxisOrder::EastNorth,
        "N" => AxisOrder::NorthEast,
        "I" => AxisOrder::Inapplicable,
        _ => return Some(Entry::Unsupported(proj)),
    };
    Some(Entry::Supported(CrsDef {
        proj: proj.to_string(),
        axis_order,
        swap: axis_order == AxisOrder::NorthEast,
        angular_unit: unit.parse().unwrap_or(DEGREE),
    }))
}

#[cfg(test)]
mod tests {
    use std::fmt::Write;

    use geo_types::Coord;

    use super::super::{Crs, find_math_transform, wkt};
    use super::*;

    /// Parse one `lon,lat,x,y,lon2,lat2;...` sample column.
    fn samples(s: &str) -> Vec<[f64; 6]> {
        s.split(';')
            .filter_map(|p| {
                let v: Vec<f64> = p.split(',').filter_map(|v| v.parse().ok()).collect();
                v.try_into().ok()
            })
            .collect()
    }

    /// Replace the datum shift of a PROJ string with the one GeoTools uses (column 8 of the `DumpEpsg` output).
    /// Returns the new string and whether GeoTools uses a wrong ellipsoid (a GeoTools bug: ellipsoids defined in
    /// feet are used as if they were in meters for Molodensky transformations).
    fn with_datum(proj: &str, datum: &str) -> Result<(String, bool), String> {
        let mut out: Vec<&str> = proj
            .split_whitespace()
            .filter(|t| !t.starts_with("+towgs84=") && !t.starts_with("+molodensky=") && *t != "+no_defs")
            .collect();
        let datum = datum.split_once(',').filter(|(a, _)| a.starts_with("a=")).map_or(datum, |(_, rest)| rest);
        let mut bug = false;
        let token = if let Some(p) = datum.strip_prefix("helmert:") {
            let v: Vec<f64> =
                p.split(',').map(|v| v.parse().map_err(|_| format!("bad helmert {p}"))).collect::<Result<_, _>>()?;
            // round away float noise from GeoTools' unit conversions
            let v: Vec<f64> = v.iter().map(|x| (x * 1e9).round() / 1e9).collect();
            if v[3..].iter().all(|x| *x == 0.0) {
                format!("+towgs84={},{},{}", v[0], v[1], v[2])
            } else {
                format!("+towgs84={},{},{},{},{},{},{}", v[0], v[1], v[2], v[3], v[4], v[5], v[6])
            }
        } else if let Some(p) = datum.strip_prefix("molodensky:") {
            let v: Vec<&str> = p.split(',').collect();
            let src_a: f64 = v[3].parse().map_err(|_| format!("bad molodensky {p}"))?;
            let a: f64 = proj
                .split_whitespace()
                .find_map(|t| t.strip_prefix("+a="))
                .and_then(|a| a.parse().ok())
                .ok_or_else(|| format!("no +a in {proj}"))?;
            bug = (src_a - a).abs() > 1e-3;
            if v[5] == "true" {
                return Err("abridged Molodensky datum shift".into());
            }
            format!("+molodensky={},{},{}", v[0], v[1], v[2])
        } else if datum == "geocentric" {
            "+towgs84=0,0,0".to_string()
        } else if datum == "identity" {
            String::new()
        } else {
            return Err(format!("unsupported datum shift {datum}"));
        };
        let token_ref = token.as_str();
        if !token_ref.is_empty() {
            out.push(token_ref);
        }
        Ok((out.join(" "), bug))
    }

    /// Regenerates `epsg.tsv.zst` from the output of `tools/crs/DumpEpsg.java`:
    ///
    /// ```sh
    /// tools/crs/java.sh DumpEpsg target/crsgen/epsg.tsv
    /// CRS_GEN_INPUT=target/crsgen/epsg.tsv cargo test -p planetiler-core --lib generate_epsg_table -- --ignored --nocapture
    /// ```
    #[test]
    #[ignore = "generator, needs CRS_GEN_INPUT"]
    fn generate_epsg_table() {
        let input = std::env::var("CRS_GEN_INPUT").expect("CRS_GEN_INPUT");
        let input = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..").join(input);
        let text = std::fs::read_to_string(&input).unwrap();
        // CRS_GEN_DEBUG=1234,5678 prints details for these codes
        let debug: Vec<u32> = std::env::var("CRS_GEN_DEBUG")
            .unwrap_or_default()
            .split(',')
            .filter_map(|c| c.trim().parse().ok())
            .collect();
        let mut out = String::new();
        let mut report = String::new();
        let (mut exact, mut close, mut approx, mut bugs, mut no_samples, mut unsupported, mut skipped) =
            (0, 0, 0, 0, 0, 0, 0);
        let mut worst: Vec<(f64, u32, String)> = vec![];
        let mut forward_mismatch = 0;
        let mut unsupported_line = |out: &mut String, report: &mut String, code: u32, e: String| {
            unsupported += 1;
            let _ = writeln!(report, "unsupported {code}: {e}");
            let _ = writeln!(out, "{code}\tX\t{}", e.replace(['\t', '\n'], " "));
        };
        for line in text.lines() {
            let cols: Vec<&str> = line.split('\t').collect();
            let code: u32 = cols[0].parse().unwrap();
            if cols[1] == "ERR" || cols.len() < 8 {
                skipped += 1;
                continue;
            }
            let order = match cols[2] {
                "EAST_NORTH" => "E",
                "NORTH_EAST" => "N",
                _ => "I",
            };
            let mut def = match wkt::wkt_to_def(cols[6], &|_| None) {
                Ok(def) => def,
                Err(e) => {
                    unsupported_line(&mut out, &mut report, code, format!("{e:#}"));
                    continue;
                }
            };
            let bug = match with_datum(&def.proj, cols[7]) {
                Ok((proj, bug)) => {
                    def.proj = proj;
                    bug
                }
                Err(e) => {
                    unsupported_line(&mut out, &mut report, code, e);
                    continue;
                }
            };
            // verify against the GeoTools reference coordinates (longitude-first variant of the CRS)
            let geographic = cols[1] == "G";
            if debug.contains(&code) {
                eprintln!("{code}: {}", def.proj);
            }
            let mut max_deg: f64 = 0.0;
            let mut max_lin: f64 = 0.0;
            let mut error = None;
            let samples = samples(cols[5]);
            match Crs::from_def(def.clone(), format!("EPSG:{code}")) {
                Ok(crs) => {
                    let crs = crs.with_swap(false);
                    let inv = find_math_transform(&crs, &Crs::wgs84(), None);
                    let fwd = find_math_transform(&Crs::wgs84(), &crs, None);
                    for &[lon, lat, x, y, lon2, lat2] in &samples {
                        match (fwd.transform(Coord { x: lon, y: lat }), inv.transform(Coord { x, y })) {
                            (Ok(xy), Ok(ll)) => {
                                let dlon = (ll.x - lon2).abs() % 360.0;
                                let dlon = dlon.min(360.0 - dlon);
                                let mut dx = (xy.x - x).abs();
                                if geographic {
                                    dx %= 360.0;
                                    dx = dx.min(360.0 - dx);
                                }
                                max_deg = max_deg.max(dlon).max((ll.y - lat2).abs());
                                max_lin = max_lin.max(dx).max((xy.y - y).abs());
                                if debug.contains(&code) {
                                    eprintln!(
                                        "{code} {lon},{lat} -> {xy:?} (java {x},{y}); {x},{y} -> {ll:?} (java {lon2},{lat2})"
                                    );
                                }
                            }
                            (Err(e), _) | (_, Err(e)) => error = Some(format!("{e:#}")),
                        }
                    }
                }
                Err(e) => error = Some(format!("{e:#}")),
            }
            if let Some(e) = error {
                unsupported_line(&mut out, &mut report, code, format!("{e} ({})", def.proj));
                continue;
            }
            // the inverse (CRS -> WGS84, what readers use) error is in degrees; the forward error (used to filter by
            // bounds) is in CRS units, or degrees for geographic CRS
            let (deg_err, lin_err) = (max_deg, max_lin);
            let lin_tolerance = if geographic { 1e-7 } else { 0.01 };
            if samples.is_empty() {
                no_samples += 1;
            } else if bug {
                bugs += 1;
                let _ = writeln!(report, "geotools-bug {code}: inverse={deg_err:e} forward={lin_err:e} {}", def.proj);
            } else if deg_err <= 1e-7 {
                exact += 1;
            } else if deg_err <= 1e-6 {
                close += 1;
            } else {
                approx += 1;
                worst.push((deg_err, code, format!("inverse={deg_err:e} forward={lin_err:e} {}", def.proj)));
            }
            if !bug && !samples.is_empty() && lin_err > lin_tolerance * 10.0 {
                forward_mismatch += 1;
                let _ = writeln!(report, "forward {code}: inverse={deg_err:e} forward={lin_err:e} {}", def.proj);
            }
            let unit =
                if (def.angular_unit - DEGREE).abs() > 1e-15 { format!(":{}", def.angular_unit) } else { "".into() };
            let _ = writeln!(out, "{code}\t{order}{unit}\t{}", def.proj);
        }
        worst.sort_by(|a, b| b.0.total_cmp(&a.0));
        for (_, code, msg) in &worst {
            let _ = writeln!(report, "approx {code}: {msg}");
        }
        eprintln!("{report}");
        eprintln!(
            "CRS -> WGS84 vs GeoTools: <=1e-7 deg: {exact}, <=1e-6 deg: {close}, worse: {approx}, GeoTools bug \
             (ellipsoid unit): {bugs}, no reference coordinates: {no_samples}, unsupported: {unsupported}, skipped \
             (GeoTools fails): {skipped}; WGS84 -> CRS differs by > 10 cm / 1e-6 deg: {forward_mismatch}"
        );
        let compressed = zstd::stream::encode_all(out.as_bytes(), 19).unwrap();
        let dest = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src/geo/crs/epsg.tsv.zst");
        std::fs::write(&dest, &compressed).unwrap();
        eprintln!("wrote {} ({} bytes, {} uncompressed)", dest.display(), compressed.len(), out.len());
    }
}
